<?php
require_once __DIR__.'/../includes/member.php'; $user=require_login(); if($user['role']==='admin') redirect('admin/dashboard.php');
$filters=[];$params=[];$q=trim($_GET['q']??''); foreach(['author'=>'author','year'=>'year','genre'=>'genre','publisher'=>'p.name'] as $key=>$col){if(!empty($_GET[$key])){$filters[]="$col LIKE ?";$params[]='%'.trim($_GET[$key]).'%';}} if($q!==''){$filters[]='(b.title LIKE ? OR b.author LIKE ?)';$params[]="%$q%";$params[]="%$q%";}
$sql='SELECT b.*,p.name publisher FROM books b LEFT JOIN publishers p ON p.id=b.publisher_id'.($filters?' WHERE '.implode(' AND ',$filters):'').' ORDER BY b.title';$books=rows($sql,$params);$selected=!empty($_GET['book'])?one('SELECT b.*,p.name publisher FROM books b LEFT JOIN publishers p ON p.id=b.publisher_id WHERE b.id=?',[(int)$_GET['book']]):null;
member_start('Katalog Buku',$user,'katalog.php'); ?>
<section class="member-section"><div class="member-section-heading"><div><span class="member-kicker">TEMUKAN BACAAN</span><h1>Katalog Buku</h1></div></div><form class="member-filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Cari judul atau penulis"><input name="author" value="<?=e($_GET['author']??'')?>" placeholder="Penulis"><input name="publisher" value="<?=e($_GET['publisher']??'')?>" placeholder="Penerbit"><input name="year" value="<?=e($_GET['year']??'')?>" placeholder="Tahun terbit"><input name="genre" value="<?=e($_GET['genre']??'')?>" placeholder="Kategori"><button type="submit">Cari buku</button></form><div class="member-book-grid"><?php foreach($books as $book) member_book_card($book); ?><?php if(!$books):?><p class="member-empty">Buku tidak ditemukan.</p><?php endif;?></div></section>
<?php member_end($selected); ?>
